def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    objects = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects.append((max(c for _, c in cells), color, cells))

    # Objects slide right, with objects farther right settling first.
    objects.sort(reverse=True)
    for _, color, cells in objects:
        for r, c in cells:
            out[r][c] = 0

        shift = 0
        while True:
            next_shift = shift + 1
            if any(c + next_shift >= w or out[r][c + next_shift] != 0
                   for r, c in cells):
                break
            shift = next_shift

        for r, c in cells:
            out[r][c + shift] = color

    return out
